void setup() {
  pinMode(4, OUTPUT);
}

void loop() {
  for (int b = 0; b <= 255; b++) {
    analogWrite(4, b);
    delay(5);
  }
  for (int b = 255; b >= 0; b--) {
    analogWrite(4, b);
    delay(5);
  }
}

